import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { createHmac } from 'node:crypto';
import {
    attachmentBody, buildFrankedReport, buildStoredFranking, canonMessage, commit, frankBody, frankForSend,
    frankingHeaders, frankingFieldsAfterEdit, hashFileForCommitment, ingestInboundFranking, isWireFranking,
    sha256B64, takeSealedFranking, withoutFranking, MAX_HASHED_FILE_BYTES, FRANKING_HEADER,
    type FrankKind, type StoredFranking,
} from './franking';

/**
 * The golden vectors were generated by an INDEPENDENT implementation and are
 * asserted byte for byte by the API's own test too (apps/api/src/franking/
 * franking.protocol.spec.ts): a drift in either implementation fails a test
 * instead of silently making every commitment unverifiable.
 */
const vectors = JSON.parse(readFileSync(new URL('./franking.vectors.json', import.meta.url), 'utf8'));
const hex = (u: Uint8Array) => Buffer.from(u).toString('hex');
const b64 = (u: Uint8Array) => Buffer.from(u).toString('base64');

const SENDER = '0a1b2c3d-4e5f-4a6b-8c7d-9e0f1a2b3c4d';
const DEVICE = '1b2c3d4e-5f6a-4b7c-8d9e-0f1a2b3c4d5e';
const CONV = '2c3d4e5f-6a7b-4c8d-9e0f-1a2b3c4d5e6f';
const CHAN = '3d4e5f6a-7b8c-4d9e-8f1a-2b3c4d5e6f7a';
const ROW = '5f6a7b8c-9d0e-4f1a-8b3c-4d5e6f7a8b9c';
const RECIPIENT = '4e5f6a7b-8c9d-4e0f-9a2b-3c4d5e6f7a8b';

describe('golden vectors', () => {
    for (const c of vectors.cases) {
        it(`reproduces "${c.name}"`, async () => {
            const input = { ...c.message, kind: c.message.kind as FrankKind };
            expect(hex(canonMessage(input))).toBe(c.canon_message_hex);
            const kf = new Uint8Array(Buffer.from(vectors.kf_hex, 'hex'));
            expect(b64(await commit(kf, input))).toBe(c.commitment_b64);
        });
    }

    it('rebuilds the attachment body the vectors committed to', () => {
        const att = vectors.cases.find((c: { message: { kind: string } }) => c.message.kind === 'attachment');
        expect(attachmentBody(vectors.attachment)).toBe(att.message.body);
    });

    it('frankBody yields the same kind and body for each vector message', () => {
        expect(frankBody({ type: 'text', text: 'hi channel' })).toEqual({ kind: 'text', body: 'hi channel' });
        expect(frankBody({ type: 'klipy_gif', slug: vectors.klipy.slug, media: { url: vectors.klipy.url } }))
            .toEqual({ kind: 'klipy_gif', body: vectors.cases.find((c: { message: { kind: string } }) => c.message.kind === 'klipy_gif').message.body });
        expect(frankBody({ type: 'attachment', ...vectors.attachment, content_sha256_b64: vectors.attachment.sha256_b64 }))
            .toEqual({ kind: 'attachment', body: vectors.cases.find((c: { message: { kind: string } }) => c.message.kind === 'attachment').message.body });
    });
});

describe('frankBody - what is reportable', () => {
    it('text and edits with text', () => {
        expect(frankBody({ type: 'text', text: 'a' })).toEqual({ kind: 'text', body: 'a' });
        expect(frankBody({ type: 'edit', target_id: 't', text: 'b' })).toEqual({ kind: 'text', body: 'b' });
    });

    it.each([
        ['empty text', { type: 'text', text: '' }],
        ['a reaction', { type: 'reaction', target_id: 't', emoji: 'x', action: 'add' }],
        ['a delete', { type: 'delete', target_id: 't' }],
        ['a call key', { type: 'call_key', call_id: 'c' }],
        ['a pin', { type: 'pin' }],
        ['an invite', { type: 'server_invite', code: 'abc' }],
        ['an attachment with no content hash', { type: 'attachment', attachment_id: 'a', filename: 'f', mime: 'm', byte_size: 1 }],
        ['an attachment with a malformed hash', { type: 'attachment', attachment_id: 'a', filename: 'f', mime: 'm', byte_size: 1, content_sha256_b64: 'nope' }],
        ['non-objects', 'text'],
        ['null', null],
    ])('%s is not reportable', (_n, content) => {
        expect(frankBody(content)).toBeNull();
    });
});

describe('send -> relay -> receive -> report round trip', () => {
    const SERVER_KEY = Buffer.alloc(32, 9);
    const lp = (s: string | Buffer) => { const b = Buffer.isBuffer(s) ? s : Buffer.from(s, 'utf8'); const l = Buffer.alloc(4); l.writeUInt32BE(b.length); return Buffer.concat([l, b]); };

    /** A stand-in relay that follows the PROTOCOL (the API's tag), so the client is tested against it. */
    function relayTag(c64: string, o: { kind: 'dm' | 'channel'; sender: string; ctx: string; subject: string; at: number }) {
        const canon = Buffer.concat([Buffer.from('CLFTAG01'), lp('k1'), lp(o.kind), lp(Buffer.from(c64, 'base64')), lp(o.sender), lp(o.ctx), lp(o.subject), lp(String(o.at))]);
        return createHmac('sha256', SERVER_KEY).update(canon).digest('base64');
    }

    async function deliver(contentJson: string, ctx: { contextKind: 'dm' | 'channel'; contextId: string }) {
        const sent = await frankForSend(contentJson, { ...ctx, senderUserId: SENDER, senderDeviceId: DEVICE }, () => 1761840000123);
        expect(sent.commitment_b64).toBeDefined();
        const at = 1761840000456;
        const wire = { c: sent.commitment_b64!, t: relayTag(sent.commitment_b64!, { kind: ctx.contextKind, sender: SENDER, ctx: ctx.contextId, subject: ctx.contextKind === 'dm' ? RECIPIENT : ROW, at }), kid: 'k1', ts: at };
        // The recipient: decrypt (here: parse), lift `_fk`, join with the relay's tag.
        const { content, franking } = ingestInboundFranking(JSON.parse(sent.contentJson), {
            wire, contextKind: ctx.contextKind, contextId: ctx.contextId, senderUserId: SENDER, senderDeviceId: DEVICE,
            messageId: ctx.contextKind === 'channel' ? ROW : undefined,
        });
        return { sent, wire, content, franking: franking as StoredFranking };
    }

    it('seals kf INSIDE the payload and puts only c outside it', async () => {
        const json = JSON.stringify({ type: 'text', text: 'hello', client_msg_id: 'm1' });
        const sent = await frankForSend(json, { contextKind: 'dm', contextId: CONV, senderUserId: SENDER, senderDeviceId: DEVICE });
        const sealed = JSON.parse(sent.contentJson);
        expect(sealed._fk.v).toBe(1);
        expect(Buffer.from(sealed._fk.kf, 'base64')).toHaveLength(32);
        expect(sealed.text).toBe('hello');
        expect(sealed.client_msg_id).toBe('m1');
        // c reveals nothing: it is not kf, not the text, and not derivable without kf.
        expect(sent.commitment_b64).not.toBe(sealed._fk.kf);
        expect(sent.commitment_b64).toMatch(/^[A-Za-z0-9+/]{43}=$/);
        expect(sent.commitment_b64).not.toContain('hello');
        // ...and it is the only thing that goes in the header.
        expect(frankingHeaders(sent)).toEqual({ [FRANKING_HEADER]: sent.commitment_b64 });
    });

    it('uses a fresh kf per message', async () => {
        const json = JSON.stringify({ type: 'text', text: 'same' });
        const ctx = { contextKind: 'dm' as const, contextId: CONV, senderUserId: SENDER, senderDeviceId: DEVICE };
        const a = await frankForSend(json, ctx);
        const b = await frankForSend(json, ctx);
        expect(JSON.parse(a.contentJson)._fk.kf).not.toBe(JSON.parse(b.contentJson)._fk.kf);
        expect(a.commitment_b64).not.toBe(b.commitment_b64);
    });

    it.each([['dm', CONV], ['channel', CHAN]] as const)('a %s message verifies on the way back and builds the report payload', async (kind, ctxId) => {
        const { content, franking, wire } = await deliver(JSON.stringify({ type: 'text', text: 'you are all idiots' }), { contextKind: kind, contextId: ctxId });
        expect('_fk' in (content as object)).toBe(false);          // kf never reaches the stored content
        expect(franking.c_b64).toBe(wire.c);
        const res = await buildFrankedReport({ content, franking, sender_user_id: SENDER });
        expect(res.ok).toBe(true);
        if (!res.ok) return;
        expect(res.franked).toMatchObject({
            kind: 'text', text: 'you are all idiots', sender_user_id: SENDER, sender_device_id: DEVICE,
            context_kind: kind, context_id: ctxId, client_ts_ms: 1761840000123, received_at_ms: 1761840000456,
            kid: 'k1', c_b64: wire.c, t_b64: wire.t,
        });
        expect(res.franked.message_id).toBe(kind === 'channel' ? ROW : undefined);
    });

    it('an attachment and a GIF round-trip too', async () => {
        const sha = await sha256B64(new TextEncoder().encode('file bytes'));
        const att = await deliver(JSON.stringify({ type: 'attachment', attachment_id: ROW, filename: 'cat.png', mime: 'image/png', byte_size: 10, content_sha256_b64: sha, file_key_b64: 'k', file_nonce_b64: 'n' }), { contextKind: 'dm', contextId: CONV });
        const r1 = await buildFrankedReport({ content: att.content, franking: att.franking, sender_user_id: SENDER });
        expect(r1.ok && r1.franked.attachment).toEqual({ attachment_id: ROW, filename: 'cat.png', mime: 'image/png', byte_size: 10, sha256_b64: sha });
        // The file KEY is never part of the report payload.
        expect(JSON.stringify(r1)).not.toContain('file_key_b64');
        const gif = await deliver(JSON.stringify({ type: 'klipy_gif', slug: 'cat', media: { url: 'https://static.klipy.com/a.gif' } }), { contextKind: 'channel', contextId: CHAN });
        const r2 = await buildFrankedReport({ content: gif.content, franking: gif.franking, sender_user_id: SENDER });
        expect(r2.ok && r2.franked.klipy).toEqual({ slug: 'cat', url: 'https://static.klipy.com/a.gif' });
    });

    it('a message the user edited locally without a new commitment no longer verifies', async () => {
        const { content, franking } = await deliver(JSON.stringify({ type: 'text', text: 'original' }), { contextKind: 'dm', contextId: CONV });
        const res = await buildFrankedReport({ content: { ...(content as object), text: 'edited by someone' }, franking, sender_user_id: SENDER });
        expect(res).toEqual({ ok: false, reason: 'content_changed' });
    });

    it('other ways to fail soft: no franking, no content, wrong sender', async () => {
        const { content, franking } = await deliver(JSON.stringify({ type: 'text', text: 'x' }), { contextKind: 'dm', contextId: CONV });
        expect(await buildFrankedReport({ content })).toEqual({ ok: false, reason: 'no_franking' });
        expect(await buildFrankedReport({ content: { type: 'reaction' }, franking })).toEqual({ ok: false, reason: 'no_content' });
        expect(await buildFrankedReport({ content, franking, sender_user_id: '9a1b2c3d-4e5f-4a6b-8c7d-9e0f1a2b3c4d' })).toEqual({ ok: false, reason: 'sender_mismatch' });
        expect(await buildFrankedReport({ content, franking: { ...franking, kf_b64: '!!' } })).toEqual({ ok: false, reason: 'malformed' });
    });

    it('the relay tag is carried through untouched (the client cannot and does not alter t)', async () => {
        const { franking, wire } = await deliver(JSON.stringify({ type: 'text', text: 'x' }), { contextKind: 'dm', contextId: CONV });
        expect(franking.t_b64).toBe(wire.t);
        expect(franking.kid).toBe('k1');
        expect(franking.received_at_ms).toBe(wire.ts);
    });
});

describe('frankForSend fails soft', () => {
    const ctx = { contextKind: 'dm' as const, contextId: CONV, senderUserId: SENDER, senderDeviceId: DEVICE };

    it.each([
        ['a reaction', JSON.stringify({ type: 'reaction', target_id: 't', emoji: 'x', action: 'add' })],
        ['a control message', JSON.stringify({ type: 'call_key', call_id: 'c' })],
        ['invalid JSON', '{not json'],
        ['a non-object', '"just a string"'],
    ])('leaves %s alone: same content, no commitment', async (_n, json) => {
        const out = await frankForSend(json, ctx);
        expect(out).toEqual({ contentJson: json });
        expect(frankingHeaders(out)).toEqual({});
    });

    it.each([
        ['no sender', { ...ctx, senderUserId: undefined }],
        ['no device', { ...ctx, senderDeviceId: null }],
        ['a non-UUID conversation', { ...ctx, contextId: 'not-a-uuid' }],
    ])('does not frank with %s - and never throws', async (_n, bad) => {
        const json = JSON.stringify({ type: 'text', text: 'hi' });
        expect(await frankForSend(json, bad)).toEqual({ contentJson: json });
    });

    it('overwrites a copied-along _fk rather than trusting it', async () => {
        const json = JSON.stringify({ type: 'text', text: 'hi', _fk: { v: 1, kf: 'AAAA', ts: 1 } });
        const out = await frankForSend(json, ctx);
        const sealed = JSON.parse(out.contentJson);
        expect(sealed._fk.kf).not.toBe('AAAA');
        expect(Buffer.from(sealed._fk.kf, 'base64')).toHaveLength(32);
    });
});

describe('takeSealedFranking - the receive boundary', () => {
    const kf = Buffer.alloc(32, 5).toString('base64');

    it('removes _fk from any content, valid or not, so it can never reach state or a backup', () => {
        for (const fk of [{ v: 1, kf, ts: 5 }, { v: 2, kf, ts: 5 }, { v: 1, kf: 'short', ts: 5 }, 'junk', null, 7]) {
            const { content } = takeSealedFranking({ type: 'text', text: 'x', _fk: fk });
            expect('_fk' in (content as object)).toBe(false);
            expect((content as { text: string }).text).toBe('x');
        }
    });

    it('returns the key only when it is well formed', () => {
        expect(takeSealedFranking({ _fk: { v: 1, kf, ts: 5 } }).fk).toEqual({ kf_b64: kf, ts: 5 });
        expect(takeSealedFranking({ _fk: { v: 1, kf, ts: -1 } }).fk).toBeNull();
        expect(takeSealedFranking({ _fk: { v: 1, kf, ts: 1.5 } }).fk).toBeNull();
        expect(takeSealedFranking({ _fk: { v: 2, kf, ts: 5 } }).fk).toBeNull();
        expect(takeSealedFranking({ _fk: { v: 1, kf: 'AAAA', ts: 5 } }).fk).toBeNull();
        expect(takeSealedFranking({ type: 'text' }).fk).toBeNull();
    });

    it('passes non-objects through untouched', () => {
        expect(takeSealedFranking('x')).toEqual({ content: 'x', fk: null });
        expect(takeSealedFranking(null)).toEqual({ content: null, fk: null });
    });
});

describe('buildStoredFranking', () => {
    const fk = { kf_b64: Buffer.alloc(32, 5).toString('base64'), ts: 5 };
    const wire = { c: Buffer.alloc(32, 1).toString('base64'), t: Buffer.alloc(32, 2).toString('base64'), kid: 'k1', ts: 9 };
    const args = { fk, wire, contextKind: 'dm' as const, contextId: CONV, senderUserId: SENDER, senderDeviceId: DEVICE };

    it('needs BOTH halves: the sender\'s key and the relay\'s tag', () => {
        expect(buildStoredFranking(args)).toBeDefined();
        expect(buildStoredFranking({ ...args, fk: null })).toBeUndefined();          // old-client sender
        expect(buildStoredFranking({ ...args, wire: undefined })).toBeUndefined();   // old / non-franking relay
    });

    it('refuses a malformed relay object', () => {
        for (const bad of [{ ...wire, c: 'x' }, { ...wire, t: 5 }, { ...wire, kid: 'a/b' }, { ...wire, ts: 'now' }, [], 'x']) {
            expect(isWireFranking(bad)).toBe(false);
            expect(buildStoredFranking({ ...args, wire: bad })).toBeUndefined();
        }
    });

    it('needs UUID ids, and a row id for a channel message', () => {
        expect(buildStoredFranking({ ...args, contextId: 'x' })).toBeUndefined();
        expect(buildStoredFranking({ ...args, senderUserId: null })).toBeUndefined();
        expect(buildStoredFranking({ ...args, contextKind: 'channel' })).toBeUndefined();
        expect(buildStoredFranking({ ...args, contextKind: 'channel', messageId: ROW })?.message_id).toBe(ROW);
    });

    it('lower-cases ids to match the canonical form', () => {
        const f = buildStoredFranking({ ...args, senderUserId: SENDER.toUpperCase() })!;
        expect(f.sender_user_id).toBe(SENDER);
    });
});

describe('edits replace what vouches for a message', () => {
    const franking = { v: 1 } as unknown as StoredFranking;
    const edit = { v: 2 } as unknown as StoredFranking;

    it('an edit carrying its own franking replaces the original\'s', () => {
        const row = { id: 'm', franking, content: { text: 'old' } };
        const next = { ...withoutFranking(row), ...frankingFieldsAfterEdit({ franking: edit }) };
        expect((next as { franking?: unknown }).franking).toBe(edit);
    });

    it('an edit WITHOUT franking drops the original\'s (the old proof must not vouch for new text)', () => {
        const row = { id: 'm', franking, content: { text: 'old' } };
        const next = { ...withoutFranking(row), ...frankingFieldsAfterEdit({}) };
        expect('franking' in next).toBe(false);
    });
});

describe('attachment hashing', () => {
    it('hashes a file the same way WebCrypto does', async () => {
        const bytes = new TextEncoder().encode('cat bytes');
        const blob = new Blob([bytes]);
        const expected = (await import('node:crypto')).createHash('sha256').update('cat bytes').digest('base64');
        expect(await hashFileForCommitment(blob)).toBe(expected);
        expect(await sha256B64(bytes)).toBe(expected);
    });

    it('declines a file over the cap, and an unreadable one, without throwing', async () => {
        expect(await hashFileForCommitment({ size: MAX_HASHED_FILE_BYTES + 1 } as unknown as Blob)).toBeUndefined();
        expect(await hashFileForCommitment({ size: 1, arrayBuffer: async () => { throw new Error('nope'); } } as unknown as Blob)).toBeUndefined();
    });
});
